sng.content:
@version: 4.11
@include "scl.conf"
options { keep-hostname(yes); chain-hostnames(no); use-dns(no); };
source s_net { udp(port(514)); tcp(port(601)); };
destination d_host { file("/var/log/remote/$${SOURCEIP}/$${YEAR}-$${MONTH}-$${DAY}.log" create-dirs(yes) dir-perm(0755) perm(0644)); };
log { source(s_net); destination(d_host); };
